select le1_0.id from labels le1_0 order by 1
select o1_1.id,o1_1.status,o1_1.total,le1_0.id from labels le1_0 join order_labels o1_0 on le1_0.id=o1_0.label_id join orders o1_1 on o1_1.id=o1_0.order_id left join customers r1_0 on r1_0.id=o1_1.referrer_id where o1_1.id<=? and exists(select 1 from customers ce1_0 where ce1_0.id<=? and ce1_0.name=r1_0.name) and le1_0.id in (?,?,?,?,?,?,?,?,?,?) order by 1
